const waveId = $flow.inParams.wave_id;
if (!$utils.isDefined(waveId)) {
    throw new Error('wave_id is required.');
}
let released = 0;
const shipments = (await $datasources.Utilities.ds_get_wave_shipments.get({ wave_id: waveId })).result ?? [];
for (const shipment of shipments) {
    try {
        await $flows.Utilities.crud_update_entity({ entity: 'Shipments', keys: [{ name: 'Id', value: shipment.Id }], properties: { StatusId: 4 } });
        released++;
    } catch (e) {
        // skip shipments that fail to update
    }
}
$flow.outParams.released_count = released;

